        }
		
		private void BuildSearchFieldsGenerated(TaskTypePM entityPM, TaskType entityPOCO, bool isNewEntity)
        {
            string mySearchFields = "";
			
           
            entityPM.SearchFields += mySearchFields;
            entityPOCO.SearchFields += mySearchFields;
        }
			  
